// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.componentsimport androidx.compose.animation.core.LinearEasingimport androidx.compose.animation.core.RepeatModeimport androidx.compose.animation.core.animateFloatimport androidx.compose.animation.core.infiniteRepeatableimport androidx.compose.animation.core.rememberInfiniteTransitionimport androidx.compose.animation.core.tweenimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.borderimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Boltimport androidx.compose.material.icons.filled.Memoryimport androidx.compose.material.icons.filled.NetworkWifiimport androidx.compose.material.icons.filled.Thermostatimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.alphaimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.theme.AccentAuroraStartimport com.roshan.persona.ui.theme.AccentSuccessimport com.roshan.persona.ui.theme.AccentWarnimport com.roshan.persona.ui.theme.brainLayerColor/** * Brain Bar — top status bar showing real-time brain + device state. * * Wired to [com.roshan.persona.ui.state.UiStateProvider]: *   - brainHealthPercent    → ⚡ 87% *   - activeBrainLayer      → L4 ☁ (pulsing when active) *   - lastBrainLatencyMs    → ⏱ 420ms *   - lastBrainCostUsd      → $0.001 *   - memoryCount           → 🧠 42mem *   - batteryLevel          → 🔋 87% *   - thermalStatus         → 🌡 Cool *   - networkStatus         → 📶 WiFi * * @param brainHealth 0-100 * @param activeLayer e.g. "L4" or null * @param latencyMs last request latency * @param costUsd last request cost * @param memoryCount total memories in store * @param battery 0-100 * @param isCharging charging state * @param thermal thermal status string (e.g. "Cool", "Moderate") * @param network network status string (e.g. "WiFi", "Offline") * @param onClick tap handler (usually opens Brain Activity overlay) */@Composablefun BrainBar(    brainHealth: Int,    activeLayer: String?,    latencyMs: Long,    costUsd: Float,    memoryCount: Int,    battery: Int,    isCharging: Boolean,    thermal: String,    network: String,    onClick: () -> Unit,    modifier: Modifier = Modifier,) {    val infinite = rememberInfiniteTransition(label = "brain_bar_pulse")    val pulseAlpha by infinite.animateFloat(        initialValue = 0.4f,        targetValue = 1f,        animationSpec = infiniteRepeatable(            animation = tween(1200, easing = LinearEasing),            repeatMode = RepeatMode.Reverse,        ),        label = "pulse_alpha",    )    val layerColor = brainLayerColor(activeLayer)    val batteryColor = when {        battery > 50 -> AccentSuccess        battery > 20 -> AccentWarn        else -> com.roshan.persona.ui.theme.AccentDanger    }    val thermalColor = when (thermal) {        "Cool", "Light" -> AccentSuccess        "Moderate" -> AccentWarn        "Severe", "Critical", "Emergency" -> com.roshan.persona.ui.theme.AccentDanger        else -> MaterialTheme.colorScheme.onSurfaceVariant    }    val networkColor = if (network == "Offline") MaterialTheme.colorScheme.outline else AccentSuccess    Row(        modifier = modifier            .fillMaxWidth()            .background(                color = MaterialTheme.colorScheme.surface.copy(alpha = 0.9f),                shape = RoundedCornerShape(16.dp),            )            .border(                width = 1.dp,                color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f),                shape = RoundedCornerShape(16.dp),            )            .padding(horizontal = 12.dp, vertical = 8.dp),        verticalAlignment = Alignment.CenterVertically,        horizontalArrangement = Arrangement.spacedBy(8.dp),    ) {        // Brain health        Icon(            imageVector = Icons.Default.Bolt,            contentDescription = "Brain health",            tint = AccentAuroraStart,            modifier = Modifier.size(14.dp),        )        Text(            text = "$brainHealth%",            style = MaterialTheme.typography.labelMedium,            color = MaterialTheme.colorScheme.onSurface,        )        // Active layer (pulsing)        if (activeLayer != null) {            Box(                modifier = Modifier                    .size(width = 36.dp, height = 20.dp)                    .alpha(if (activeLayer != "—") pulseAlpha else 0.5f)                    .background(                        color = layerColor.copy(alpha = 0.25f),                        shape = RoundedCornerShape(8.dp),                    )                    .border(                        width = 1.dp,                        color = layerColor,                        shape = RoundedCornerShape(8.dp),                    ),                contentAlignment = Alignment.Center,            ) {                Text(                    text = activeLayer,                    style = MaterialTheme.typography.labelSmall,                    color = layerColor,                )            }        }        Spacer(modifier = Modifier.weight(1f))        // Latency        if (latencyMs > 0) {            Text(                text = "${latencyMs}ms",                style = MaterialTheme.typography.labelSmall,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )        }        // Cost        if (costUsd > 0) {            Text(                text = "$%.4f".format(costUsd),                style = MaterialTheme.typography.labelSmall,                color = AccentWarn,            )        }        // Memory count        Icon(            imageVector = Icons.Default.Memory,            contentDescription = "Memory count",            tint = MaterialTheme.colorScheme.onSurfaceVariant,            modifier = Modifier.size(14.dp),        )        Text(            text = "${memoryCount}mem",            style = MaterialTheme.typography.labelSmall,            color = MaterialTheme.colorScheme.onSurfaceVariant,        )        // Battery        Text(            text = "$battery%",            style = MaterialTheme.typography.labelSmall,            color = batteryColor,        )        // Thermal        Icon(            imageVector = Icons.Default.Thermostat,            contentDescription = "Thermal status",            tint = thermalColor,            modifier = Modifier.size(14.dp),        )        // Network        Icon(            imageVector = Icons.Default.NetworkWifi,            contentDescription = "Network status",            tint = networkColor,            modifier = Modifier.size(14.dp),        )    }}